head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > enterKeyPanelToggle]<br/>Accordion 컴포넌트에서 Enter 키로 패널을 열고 닫을지 설정합니다.",
    "validation" : [
        "enterKeyPanelToggle=true (default) 설정 시 포커스된 패널 타이틀에서 Enter 키를 누르면 해당 패널이 열리거나 닫힙니다.",
        "enterKeyPanelToggle=true 설정 시 패널이 열리거나 닫힌 후 onclick 이벤트가 발생합니다.",
        "enterKeyPanelToggle=false 설정 시 Enter 키를 눌러도 패널 토글이 동작하지 않습니다.",
        "enterKeyPanelToggle=false 설정 시 Enter 키의 브라우저 기본 동작이 유지됩니다.",
        "개별 Panel 단위로 Enter 키 동작을 제어하는 것은 지원하지 않으며, accordion 전체에 일괄 적용됩니다.",
        "Enter 키로 패널 토글이 활성화된 상태에서 패널이 열릴지 닫힐지는 collapsible 속성과 independentPanel 속성에 따라 결정됩니다.",
        "enterKeyPanelToggle 속성을 생략하면 기본값 true 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        enterKeyPanelToggle : con_enterKeyPanelToggle.getText(),
        collapsible : con_collapsible.getText(),
        independentPanel : con_independentPanel.getText(),
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* 시나리오 : panelTitle 포커스 버튼 클릭 후 Enter 키 입력하여 동작 확인"', '', 'label1');
    $c.gcm.createLabel('label="* enterKeyPanelToggle=true : Enter 키로 포커스된 패널 토글 / =false : Enter 키 무시 (브라우저 기본 동작 유지)"', '', 'label2');
    $c.gcm.createLabel('label="* collapsible 과 independentPanel 이 Enter 키 토글 시 패널 열림/닫힘 결정"', '', 'label3');
    $c.gcm.createLabel('label="* enterKeyPanelToggle 은 accordion 전체 일괄 적용, 개별 Panel 단위 제어는 지원하지 않음"', '', 'label4');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onclick (panel, open) - @propval true : 패널 열린/닫힌 후 onclick 이벤트 발생
scwin.target1_onclick = function (panel, open) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("panel.id : " + (panel ? panel.id : "null"));
    wf_body_bottom.getObj("scwin").setReturnValue("open : " + open);
};



// par_panelId 의 panelTitle 영역에 포커스 (accessibility=true 면 a태그, false 면 panelTitle div 에 tabindex 부여 후 포커스)
scwin.btn_focusPanelTitle_onclick = function (e) {
    let panelId = par_panelId.getValue();
    let titleEl = target1.render.querySelector("[id$='_panel_" + panelId + "_title']");
    if (titleEl) {
        let focusTarget = titleEl.querySelector("a") || titleEl;
        if (!focusTarget.hasAttribute("tabindex")) {
            focusTarget.setAttribute("tabindex", "0");
        }
        focusTarget.focus();
        wf_body_bottom.getObj("scwin").setReturnValue("===== '" + panelId + "' panelTitle 포커스 =====");
        wf_body_bottom.getObj("scwin").setReturnValue("focused tagName : " + document.activeElement.tagName);
        wf_body_bottom.getObj("scwin").setReturnValue("focused id : " + document.activeElement.id);
    }
};



// 현재 열린 패널 정보 출력 (Enter 키 토글 전/후 상태 확인용)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
